function verified(id){return verifiedSlip===id&&Date.now()<verifyUntil;}
function download(filename,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openDialog(title,body){const dialog=$('#dialog');const active=document.activeElement;dialogReturn=active instanceof HTMLElement&&active!==document.body&&!dialog.contains(active)?active:null;dialogFocus='';dialog.innerHTML=`<div class="panel-head"><h2 id="dialog-title">${esc(title)}</h2><button class="btn icon-btn" data-action="close-dialog" aria-label="ปิด">${icon('close')}</button></div>${body}`;dialog.showModal();}
/* After any close (Escape, Cancel, backdrop, verify, expiry or route change) return focus to a connected, sensible control. */
function restoreDialogFocus(){const dialog=$('#dialog');const active=document.activeElement;const target=[dialogFocus&&$(dialogFocus),dialogReturn].find(el=>el?.isConnected);dialogReturn=null;dialogFocus='';if(!active||active===document.body||dialog.contains(active)||!active.isConnected)(target||$('#main'))?.focus();}
function setMenu(open,{restore=true}={}){const side=$('#sidebar');if(!side)return;side.classList.toggle('open',open);$('.drawer-shade')?.classList.toggle('open',open);$('.mobile-menu')?.setAttribute('aria-expanded',String(open));/* While the drawer is open, the page behind it and the skip link are inert. */for(const el of [$('.shell'),$('.skip-link')])if(el)el.inert=open;if(open)($('.sidebar .nav-link.active')||$('.sidebar .nav-link'))?.focus();else if(restore)$('.mobile-menu')?.focus();}
const menuOpen=()=>!!$('#sidebar')?.classList.contains('open');
const routeInfo=()=>{const parts=(location.hash.slice(1)||'home').split('/');return {page:parts[0],id:parts[1]};};
const titles={home:'วันนี้',attendance:'ประวัติการทำงาน',day:'รายละเอียดวันทำงาน',correction:'แก้ไขเวลา',requests:'คำขอของฉัน',request:'รายละเอียดคำขอ',leave:'การลา','leave-new':'ขอลา',holidays:'วันหยุด',customize:'จัดเมนูลัด',announcements:'ประกาศ',announcement:'รายละเอียดประกาศ',notifications:'การแจ้งเตือน',payslips:'สลิปเงินเดือน',payslip:'รายละเอียดสลิป',profile:'โปรไฟล์',review:'พิจารณาคำขอ',policy:'นโยบายการลา',publish:'จัดการประกาศ',import:'นำเข้าสลิป',components:'Shared Action Card',gallery:'ภาพออกแบบ',plan:'แผนส่งมอบ'};
const restricted = page => ['policy','publish','import'].includes(page)?role!=='hr':page==='review'?role==='employee':false;
function navLink(id,label,ico){const {page}=routeInfo();const selected=page===id||(id==='requests'&&['request','correction'].includes(page))||(id==='attendance'&&page==='day')||(id==='leave'&&page==='leave-new')||(id==='announcements'&&page==='announcement')||(id==='payslips'&&page==='payslip');return `<a class="nav-link ${selected?'active':''}" href="#${id}" ${selected?'aria-current="page"':''}>${icon(ico)}${esc(label)}${id==='requests'&&pendingCount()?`<span class="nav-count">${pendingCount()}</span>`:''}</a>`;}
function shell(content){const {page}=routeInfo();return `<button class="drawer-shade" data-action="close-menu" tabindex="-1" aria-label="ปิดเมนู"></button><aside class="sidebar" id="sidebar" aria-label="เมนูหลัก"><a class="brand" href="#home">${pad('box')}Storage Planner</a><div class="nav-label">EMPLOYEE SELF-SERVICE</div>${navLink('home','วันนี้','home')}${navLink('attendance','ประวัติการทำงาน','history')}${navLink('requests','คำขอของฉัน','request')}${navLink('leave','การลา','leaf')}${navLink('holidays','วันหยุด','calendar')}${navLink('announcements','ประกาศ','megaphone')}${navLink('payslips','สลิปเงินเดือน','wallet')}${navLink('profile','โปรไฟล์','user')}${role!=='employee'?`<div class="nav-label">${role==='hr'?'HR WORKSPACE':'SUPERVISOR'}</div>${navLink('review','พิจารณาคำขอ','shield')}`:''}${role==='hr'?navLink('policy','นโยบายการลา','settings')+navLink('publish','จัดการประกาศ','megaphone')+navLink('import','นำเข้าสลิป','upload'):''}<div class="nav-label">DESIGN REVIEW</div>${navLink('components','ส่วนประกอบร่วม','box')}${navLink('gallery','ภาพออกแบบ 14 ภาพ','image')}${navLink('plan','แผนส่งมอบ','file')}<div class="sidebar-foot"><div class="row"><span class="avatar">${persona().initial}</span><div><strong>${esc(persona().name)}</strong><div class="small muted">${esc(persona().sub)}</div></div></div></div></aside><div class="shell"><header class="topbar"><button class="btn icon-btn mobile-menu" data-action="menu" aria-label="เปิดเมนู" aria-expanded="false" aria-controls="sidebar">${icon('menu')}</button><div class="crumb">HR / ${esc(titles[page]||'วันนี้')}</div>${tag('พื้นที่ตัวอย่าง','blue')}<a class="btn icon-btn notify" href="#notifications" aria-label="การแจ้งเตือน ${unreadCount()} รายการยังไม่อ่าน">${icon('bell')}${unreadCount()?`<span class="notify-count">${unreadCount()}</span>`:''}</a><button class="btn icon-btn" data-action="theme" aria-label="เปลี่ยนธีม">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button><span class="avatar" aria-hidden="true">${persona().initial}</span></header><div class="preview-bar"><strong>Design preview · ข้อมูลสมมติ</strong><span class="preview-note">12 ต.ค. 2569 · บันทึกเฉพาะในหน้านี้</span><label>บทบาท<select id="role"><option value="employee" ${role==='employee'?'selected':''}>พนักงาน</option><option value="supervisor" ${role==='supervisor'?'selected':''}>หัวหน้างาน</option><option value="hr" ${role==='hr'?'selected':''}>ฝ่าย HR</option></select></label><label>สถานะหน้าจอ<select id="response"><option value="normal">ปกติ</option><option value="loading">กำลังโหลด</option><option value="empty">ไม่มีข้อมูล</option><option value="error">ผิดพลาด</option><option value="denied">ไม่มีสิทธิ์</option></select></label>${btn('เริ่มตัวอย่างใหม่','reset')}</div><main id="main" tabindex="-1">${content}<footer class="view-footer">แบบสำหรับตรวจงาน · ข้อมูลและการยืนยันทั้งหมดเป็นตัวอย่าง · ฟีเจอร์ใหม่ยังไม่ได้เชื่อมระบบจริง</footer></main><nav class="bottom-nav" aria-label="ทางลัดมือถือ">${[['home','วันนี้','home'],['requests','คำขอ','request'],['leave','การลา','leaf'],['holidays','วันหยุด','calendar']].map(([id,label,ico])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ico)}${label}</a>`).join('')}</nav></div>`;}
function heading(title,sub,ico,action=''){return `<div class="page-head"><div><div class="head-title">${pad(ico)}<h1>${title}</h1></div>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;}
const panel=(title,body,action='')=>`<section class="panel">${title?`<div class="panel-head"><h2>${title}</h2>${action}</div>`:''}${body}</section>`;
function actionCard(s){return `<a class="action-card" href="#${s.id}">${pad(s.icon)}<div><div class="label">${s.label}</div><div class="sub">${s.sub}</div></div>${s.id==='requests'&&pendingCount()?`<span class="count">${pendingCount()}</span>`:''}</a>`;}
/* Correction evidence reads the matching day: recorded original punch stays separate from the effective value. */
function correctionEvidence(r){const d=state.days.find(x=>x.day===r.from);return `<dt>ออกเดิม (บันทึกจริง)</dt><dd class="mono">${d?.originalEnd||'ยังไม่มี'}</dd><dt>ออกที่มีผลตอนนี้</dt><dd class="mono">${d?.end||'ยังไม่มี'}</dd><dt>ออกที่เสนอ</dt><dd class="mono">${esc(r.proposed)}</dd>`;}
function requestRow(r){return `<a class="list-link" href="#request/${r.id}"><div class="list-row">${pad(r.type==='correction'?'clock':'leaf')}<div class="grow"><h3>${r.title}</h3><div class="sub">${dateLabel(r.from,true)}${r.from!==r.to?' – '+dateLabel(r.to,true):''}${r.units?' · '+r.units+' วัน':''}</div></div>${status(r.status)}${icon('chevron')}</div></a>`;}
function stateView(mode,{recovery}={}){const content={loading:['กำลังโหลดข้อมูล','โปรดรอสักครู่','clock'],empty:['ยังไม่มีรายการ','เมื่อมีข้อมูลของคุณ รายการจะแสดงที่นี่','file'],error:['โหลดข้อมูลไม่สำเร็จ','ข้อมูลที่บันทึกไว้ยังอยู่ ลองโหลดอีกครั้งได้','alert'],denied:['ไม่มีสิทธิ์ดูข้อมูลนี้','ติดต่อผู้ดูแล HR หากข้อมูลการเข้าถึงไม่ถูกต้อง','shield']}[mode];return `<div class="state-box">${mode==='loading'?'<span class="spinner" role="status" aria-label="กำลังโหลด"></span>':`<span class="empty-icon">${icon(content[2])}</span>`}<h2>${content[0]}</h2><p>${content[1]}</p>${recovery??(['empty','denied'].includes(mode)?link('กลับหน้าวันนี้','home','back'):btn(mode==='error'?'ลองอีกครั้ง':'กลับสู่หน้าปกติ','normal',{primary:true}))}</div>`;}
function home(){const today=state.days.at(-1);const prefs=state.preferences.filter(p=>p.visible);const upcoming=holidays.find(x=>x.date>'2026-10-12');return heading('สวัสดี มินตรา','เรื่องงานของคุณ ในที่เดียว','home')+`<div class="cols"><div class="stack"><section class="panel today-card"><div class="today-top"><div><h2>วันนี้ของคุณ</h2><div class="today-date">จันทร์ 12 ตุลาคม 2569</div></div>${tag(today.end?'ลงเวลาเรียบร้อย':'กำลังทำงาน',today.end?'success':'blue',today.end?'check':'clock')}</div><div class="clock-time mono">${today.end?'17:30':'14:53'} <small class="small muted">เวลาตัวอย่าง</small></div><p class="small muted compact">สำนักงานใหญ่ · กะ 08:30–17:30 · พัก 60 นาที</p><div class="punches"><div><div class="punch-label">${icon('clock')}เข้างาน</div><div class="punch-value mono">08:31</div></div><div><div class="punch-label">${icon('clock')}ออกงาน</div><div class="punch-value mono">${today.end||'—'}</div></div></div>${state.receipt?notice('บันทึกเวลาออก <strong>17:30</strong> ในตัวอย่างแล้ว · เลขรับ DEMO-001','success','check'):''}<div class="clock-actions ${state.receipt?'space':''}">${btn(today.end?'ลงเวลาแล้ว':state.clockBusy?'กำลังบันทึก…':'ลงเวลาออกงาน','clock',{primary:true,icon:'clock',disabled:!!today.end||state.clockBusy})}<span class="small muted">${today.end?'เวลาทำงานสุทธิ 7 ชม. 59 นาที':'ยังไม่มีเวลาออกงาน'}</span></div></section>${panel('เมนูลัด',prefs.length?`<div class="shortcut-grid">${prefs.map(p=>actionCard(shortcuts.find(s=>s.id===p.id))).join('')}</div>`:`${notice('คุณซ่อนเมนูลัดทั้งหมดแล้ว สามารถแสดงอีกครั้งได้จาก “จัดเมนู”')}`,link('จัดเมนู','customize','settings'))}${panel('คำขอล่าสุด',state.requests.slice(0,3).map(requestRow).join(''),link('ดูทั้งหมด','requests'))}</div><div class="stack">${panel('วันหยุดถัดไป',`<div class="list-row"><div class="date-tile"><strong>${date(upcoming.date).getUTCDate()}</strong>${weekday(upcoming.date)}</div><div><h3>${upcoming.name}</h3><div class="sub">${dateLabel(upcoming.date)}</div></div></div><p class="small muted space">ปฏิทินบริษัทสมมติ · สำนักงานใหญ่</p>`,link('ทั้งปี','holidays'))}${panel('การลาของคุณ',Object.entries(types).map(([key,t])=>{const b=balance(key);return `<a class="list-link" href="#leave"><div class="list-row">${pad('leaf')}<div class="grow"><h3>${t.label}</h3><div class="sub">คงเหลือพร้อมใช้</div></div><strong class="mono">${b.available} วัน</strong></div></a>`;}).join(''),link('ขอลา','leave-new','plus'))}${panel('ข่าวจาก HR',state.announcements.filter(a=>!a.read).slice(0,2).map(a=>announcementRow(a)).join(''),link('ทั้งหมด','announcements'))}</div></div>`;}
const kindLabels={WORKED:'ทำงานครบ',ONGOING:'กำลังทำงาน',UNRESOLVED:'รอตรวจสอบ',LEAVE:'ลา',NONWORKING:'วันหยุดประจำสัปดาห์'};
function dayStatus(d){const code=d.kind;return tag(kindLabels[code],{WORKED:'success',ONGOING:'blue',UNRESOLVED:'warning',LEAVE:'pending'}[code]||'',{WORKED:'check',ONGOING:'clock',UNRESOLVED:'alert',LEAVE:'leaf',NONWORKING:'calendar'}[code]);}
function attendance(){const counts=code=>state.days.filter(d=>d.kind===code).length;const rows=state.days.filter(d=>attendanceKind==='all'||d.kind===attendanceKind);const workedMinutes=state.days.filter(d=>d.kind==='WORKED').reduce((n,d)=>{const [h,m]=d.start.split(':').map(Number),[eh,em]=d.end.split(':').map(Number);return n+eh*60+em-h*60-m-60;},0);return heading('ประวัติการทำงาน','ตุลาคม 2569 · ยอดถึง 12 ต.ค. · อนาคตยังไม่นับ','history')+`<div class="metric-grid">${[['WORKED','check'],['ONGOING','clock'],['UNRESOLVED','alert'],['LEAVE','leaf']].map(([code,ico])=>`<button class="action-card metric" data-action="attendance-filter" data-kind="${code}" ${attendanceKind===code?'aria-current="true"':''}>${pad(ico)}<div><div class="label">${kindLabels[code]}</div><strong class="mono">${counts(code)}</strong><div class="sub">วัน</div></div></button>`).join('')}</div>${notice(`<strong>12 วัน</strong> = ทำงานครบ ${counts('WORKED')} + กำลังทำงาน ${counts('ONGOING')} + รอตรวจสอบ ${counts('UNRESOLVED')} + ลา ${counts('LEAVE')} + วันหยุด ${counts('NONWORKING')}<br>เวลาทำงานสุทธิของวันที่ครบ: ${Math.floor(workedMinutes/60)} ชม. ${workedMinutes%60} นาที · ยังไม่สรุปสายหรือโอทีจากข้อมูลนี้`)}<section class="panel space"><div class="filterbar"><div class="field"><label for="attendance-kind">รายการวัน</label><select id="attendance-kind"><option value="all">ทุกวัน</option>${Object.entries(kindLabels).map(([code,label])=>`<option value="${code}" ${attendanceKind===code?'selected':''}>${label}</option>`).join('')}</select></div><span class="small muted">${rows.length} วัน · ตารางตัวอย่างรายเดือน</span>${btn('ดาวน์โหลด CSV','attendance-csv',{icon:'download'})}</div><div class="table-wrap"><table><caption class="sr-only">รายการทำงานเดือนตุลาคม</caption><thead><tr><th>วันที่</th><th>เข้า</th><th>ออกที่มีผล</th><th>สถานะ</th><th>รายละเอียด</th></tr></thead><tbody>${rows.map(d=>`<tr><td>${dateLabel(d.day,true)}<div class="small muted">${weekday(d.day)}</div></td><td class="mono">${d.start||'—'}</td><td class="mono">${d.end||'—'}</td><td>${dayStatus(d)}</td><td>${link('ดูวัน','day/'+d.day,'chevron')}</td></tr>`).join('')}</tbody></table></div></section>`;}
function dayDetail(id){const d=state.days.find(x=>x.day===id);if(!d)return stateView('empty');const r=state.requests.find(x=>x.type==='correction'&&x.from===id);return heading(dateLabel(id),`รายละเอียดวันทำงาน · ${weekday(id)}`,'calendar',link('กลับประวัติ','attendance','back'))+`<div class="cols">${panel('เวลาและสถานะ',`${dayStatus(d)}<dl class="data-list space"><dt>สถานที่ทำงาน</dt><dd>สำนักงานใหญ่</dd><dt>เวลาตามกะ</dt><dd class="mono">08:30–17:30</dd><dt>เข้าเดิม</dt><dd class="mono">${d.start||'—'}</dd><dt>ออกเดิม</dt><dd class="mono">${d.originalEnd||'ยังไม่มี'}</dd><dt>ออกที่มีผล</dt><dd class="mono">${d.end||'ยังไม่มี'}</dd><dt>พักตามกะ</dt><dd>60 นาที</dd></dl>${d.kind==='UNRESOLVED'?notice('รายการที่ยังไม่ครบต้องตรวจสอบ ไม่ตีความเป็นขาดงานโดยอัตโนมัติ','warning','alert'):''}<div class="space">${r?link('ดูคำขอแก้ไข','request/'+r.id,'request'):!['NONWORKING','LEAVE','ONGOING'].includes(d.kind)?link('ขอแก้ไขเวลา','correction/'+id,'plus'):''}</div>`)}${panel('หลักฐานประกอบ',r?`${status(r.status)}<p class="space">${esc(r.reason)}</p><dl class="data-list"><dt>เสนอเวลาออก</dt><dd class="mono">${r.proposed}</dd></dl>${notice('เมื่อรับรอง ใช้เวลาที่มีผลในการสรุป และเก็บเวลาเดิมไว้ตรวจสอบ')}`:`<p class="muted">ยังไม่มีคำขอแก้ไขสำหรับวันนี้</p>`)}</div>`;}
function correctionForm(id){const d=state.days.find(x=>x.day===id);const existing=state.requests.find(r=>r.type==='correction'&&r.from===id);if(!d)return stateView('empty');if(existing&&existing.status!=='RETURNED')return requestDetail(existing.id);return heading('ขอแก้ไขเวลา',dateLabel(id),'clock',link('กลับรายละเอียด','day/'+id,'back'))+panel('เปรียบเทียบก่อนส่ง',`<p class="muted">เวลาออกเดิม: ${d.originalEnd||'ยังไม่มี'} · ไม่แก้หลักฐานเดิม</p><form id="correction-form" data-day="${id}" ${existing?`data-request="${existing.id}"`:''}><div class="field space"><label for="end-time">เวลาออกที่เสนอ</label><input type="time" id="end-time" name="end" required value="${existing?.proposed||'17:30'}"></div><div class="field"><label for="correction-reason">เหตุผล *</label><textarea id="correction-reason" name="reason" required>${esc(existing?.reason||'')}</textarea></div><div id="form-error" role="alert"></div><div class="form-actions">${link('ยกเลิก','day/'+id)}${btn('ส่งคำขอ',null,{primary:true,submit:true})}</div></form>`);}
function requests(){const q=query.trim();const rows=state.requests.filter(r=>(filter==='all'||r.status===filter)&&(!q||[r.title,r.from,r.reason].join(' ').includes(q)));return heading('คำขอของฉัน','ติดตามคำขอและกลับมาแก้ไขได้จากที่นี่','request',btn('สร้างคำขอ','create-request',{primary:true,icon:'plus'}))+panel('',`<div class="filterbar"><div class="field"><label for="request-filter">สถานะ</label><select id="request-filter"><option value="all">ทั้งหมด (${state.requests.length})</option>${Object.entries(statuses).map(([code,[label]])=>`<option value="${code}" ${filter===code?'selected':''}>${label} (${state.requests.filter(r=>r.status===code).length})</option>`).join('')}</select></div><div class="field grow"><label for="request-search">ค้นหาคำขอ</label><input id="request-search" type="search" placeholder="ประเภท วันที่ หรือเหตุผล" value="${esc(query)}"></div></div>${rows.length?rows.map(requestRow).join(''):stateView('empty',{recovery:btn('ล้างตัวกรองและคำค้น','recover-requests',{primary:true})})}`);}
function requestDetail(id){const r=state.requests.find(x=>x.id===id);if(!r)return stateView('empty');return heading(r.title,`${dateLabel(r.from)}${r.to!==r.from?' – '+dateLabel(r.to):''}`,'request',link('กลับคำขอ','requests','back'))+`<div class="cols">${panel('รายละเอียดคำขอ',`${status(r.status)}<dl class="data-list space"><dt>เลขคำขอ</dt><dd class="mono">DEMO-${r.id.toUpperCase()}</dd><dt>ผู้ขอ</dt><dd>มินตรา · EMP-DEMO-01</dd><dt>จำนวนวันลา</dt><dd>${r.units?r.units+' วัน':'ไม่ใช่คำขอลา'}</dd><dt>เหตุผล</dt><dd>${esc(r.reason)}</dd>${r.proposed?correctionEvidence(r):''}</dl>${r.returnReason?notice('<strong>เหตุผลที่ส่งกลับ</strong><br>'+esc(r.returnReason),'warning','back'):''}${r.type!=='correction'&&r.status==='PENDING'?notice(`สำรองสิทธิ์ ${r.units} วันแล้ว เมื่อรับรองจะเปลี่ยนเป็นยอดใช้สิทธิ์`):''}${r.status==='RETURNED'?`<div class="space">${link('แก้ไขและส่งใหม่',r.type==='correction'?'correction/'+r.from:'leave-new/'+r.id,'plus','primary')}</div>`:''}`)}${panel('ประวัติการพิจารณา',`<ol class="timeline">${r.history.map(([title,time,person])=>`<li><strong>${esc(title)}</strong><small>${esc(time)}</small><small>${esc(person)}</small></li>`).join('')}</ol><p class="small muted space">รายการเก็บลำดับเหตุการณ์ การส่งกลับไม่ลบคำขอเดิม</p>`)}</div>`;}
function leave(){return heading('การลา','สิทธิ์ปี 2569 · นโยบายบริษัทสมมติสำหรับตรวจแบบ','leaf',link('ขอลา','leave-new','plus','primary'))+`<div class="balance-grid">${Object.entries(types).map(([key,t])=>{const b=balance(key);return `<section class="panel balance-card"><div class="row">${pad('leaf')}<h2>${t.label}</h2></div><p class="small muted space">คงเหลือพร้อมใช้</p><div class="balance-num mono" data-balance="${key}">${b.available} <small>วัน</small></div><div class="mini-progress" aria-hidden="true"><span class="used" style="width:${b.used/b.entitlement*100}%"></span><span class="reserved" style="width:${b.reserved/b.entitlement*100}%"></span></div><div class="balance-details"><div>สิทธิ์ทั้งหมด<strong>${b.entitlement}</strong></div><div>ใช้แล้ว<strong>${b.used}</strong></div><div>สำรองไว้<strong>${b.reserved}</strong></div></div></section>`;}).join('')}</div><div class="space">${notice('คงเหลือพร้อมใช้ = สิทธิ์ทั้งหมด − ใช้แล้ว − สำรองไว้<br>ตัวอย่าง: ลาพักร้อน 12 − 2 − 2 = 8 วัน · ลาป่วยมีประวัติใช้ก่อนเดือนนี้ 10 วัน')}</div>${panel('ประวัติการลา',state.requests.filter(r=>r.type!=='correction').map(requestRow).join(''))}`;}
function chargedDays(from,to,unit){if(!validIso(from)||!validIso(to))return null;const start=date(from),end=date(to);const span=(end-start)/86400000;if(!Number.isFinite(span)||span<0||span>30)return null;if(unit==='half'&&span!==0)return null;const days=[];for(let n=0;n<=span;n++){const dt=new Date(start.getTime()+n*86400000),iso=dt.toISOString().slice(0,10);const nonworking=[0,6].includes(dt.getUTCDay())||holidays.some(h=>h.date===iso);days.push({date:iso,units:nonworking?0:unit==='half'?.5:1});}return days;}
function leaveForm(id){const r=state.requests.find(x=>x.id===id);if(r&&r.status!=='RETURNED')return requestDetail(id);return heading(r?'แก้ไขคำขอลา':'ขอลา','ตรวจวันลาและยอดที่จะใช้ ก่อนส่งคำขอ','leaf',link('กลับการลา','leave','back'))+`<div class="cols">${panel('รายละเอียดการลา',`${r?.returnReason?notice(esc(r.returnReason),'warning','back'):''}<form id="leave-form" ${r?`data-request="${r.id}"`:''}><div class="field"><label for="leave-type">ประเภทการลา</label><select id="leave-type" name="type">${Object.entries(types).map(([key,t])=>`<option value="${key}" ${r?.type===key?'selected':''}>${t.label}</option>`).join('')}</select></div><div class="half"><div class="field"><label for="leave-from">วันที่เริ่ม *</label><input type="date" id="leave-from" name="from" value="${r?.from||'2026-10-26'}" required></div><div class="field"><label for="leave-to">วันที่สิ้นสุด *</label><input type="date" id="leave-to" name="to" value="${r?.to||'2026-10-27'}" required></div></div><div class="field"><label for="leave-unit">ช่วงเวลาลา</label><select id="leave-unit" name="unit"><option value="full">เต็มวัน</option><option value="half">ครึ่งวันเช้า (วันเดียว)</option></select><span class="hint">ตัวอย่างนโยบายรองรับครึ่งวันเฉพาะวันเดียว</span></div><div class="field"><label for="leave-reason">เหตุผล *</label><textarea id="leave-reason" name="reason" required placeholder="อธิบายเหตุผลให้ผู้พิจารณาทราบ">${esc(r?.reason||'')}</textarea></div><div id="form-error" role="alert"></div><div class="form-actions">${link('ยกเลิก','leave')}${btn(r?'ส่งใหม่':'ส่งคำขอลา',null,{primary:true,submit:true})}</div></form>`)}<section class="panel" id="leave-charge" aria-live="polite"></section></div>`;}
function updateCharge(){const form=$('#leave-form');if(!form)return;const data=new FormData(form),t=data.get('type'),days=chargedDays(data.get('from'),data.get('to'),data.get('unit')),b=balance(t);const total=days?.reduce((n,d)=>n+d.units,0)||0;$('#leave-charge').innerHTML=`<h2>ตรวจยอดก่อนส่ง</h2><dl class="data-list space"><dt>พร้อมใช้ก่อนส่ง</dt><dd>${b.available} วัน</dd><dt>จะสำรองเพิ่ม</dt><dd><strong>${days?total+' วัน':'—'}</strong></dd><dt>พร้อมใช้หลังส่ง</dt><dd>${days?b.available-total+' วัน':'—'}</dd></dl>${!days?notice('วันที่ต้องเรียงตามลำดับ ช่วงไม่เกิน 31 วัน และครึ่งวันต้องเป็นวันเดียว','error','alert'):days.map(d=>`<div class="list-row"><span class="grow">${dateLabel(d.date,true)}</span>${tag(d.units?d.units+' วัน':'ไม่นับวันลา',d.units?'blue':'')}</div>`).join('')}<p class="small muted space">ไม่นับเสาร์ อาทิตย์ และวันหยุดบริษัทในปฏิทินตัวอย่าง</p>`;}
function holidaysPage(){const rows=holidays.filter(h=>h.date.startsWith(holidayYear));const groups=[...new Set(rows.map(h=>h.date.slice(0,7)))];return heading('วันหยุดประจำปี','สำนักงานใหญ่ · ปฏิทินบริษัทสมมติ','calendar')+panel('',`<div class="filterbar"><div class="field"><label for="holiday-year">ปี</label><select id="holiday-year"><option value="2026" ${holidayYear==='2026'?'selected':''}>2569 (2026)</option><option value="2027" ${holidayYear==='2027'?'selected':''}>2570 (2027)</option></select></div>${btn('ดาวน์โหลดทั้งปี','holiday-csv',{icon:'download',disabled:!rows.length})}</div>${notice('รายการเหล่านี้เป็นวันหยุดสมมติสำหรับตรวจแบบ ไม่ใช่ประกาศวันหยุดราชการ')}${rows.length?groups.map(month=>`<section class="month-group"><h3>${new Intl.DateTimeFormat('th-TH',{month:'long',timeZone:'UTC'}).format(date(month+'-01'))}</h3>${rows.filter(h=>h.date.startsWith(month)).map(h=>`<div class="list-row"><div class="date-tile"><strong>${date(h.date).getUTCDate()}</strong>${weekday(h.date)}</div><div class="grow"><h3>${h.name}</h3><div class="sub">${dateLabel(h.date)}</div></div></div>`).join('')}</section>`).join(''):`<div class="space">${stateView('empty',{recovery:btn('ดูวันหยุดปี 2569','recover-holidays',{primary:true})})}</div>`}`);}
const prefsChanged=()=>!!prefDraft&&JSON.stringify(prefDraft)!==JSON.stringify(state.preferences);
function customize(){if(!prefDraft)prefDraft=structuredClone(state.preferences);return heading('จัดเมนูลัด','เลือกแสดงและเรียงลำดับเมนูบนหน้าวันนี้','settings')+`<div class="cols">${panel('เมนูของคุณ',`<p class="small muted">${prefDraft.filter(p=>p.visible).length} / 6 เมนู · ลากจุดจับเพื่อจัดลำดับ</p><div id="shortcut-order" role="list" aria-label="ลำดับเมนูลัด">${prefDraft.map((p,index)=>{const s=shortcuts.find(x=>x.id===p.id);return `<div class="preference-row" role="listitem" data-sort-id="${s.id}"><button type="button" class="drag-handle" data-drag-id="${s.id}" aria-label="ลากเพื่อย้าย ${s.label} ลำดับที่ ${index+1} จาก 6" aria-describedby="shortcut-drag-help" aria-pressed="false">${icon('grip')}</button>${pad(s.icon)}<div class="grow"><strong>${s.label}</strong></div><label class="toggle"><input type="checkbox" data-shortcut="${s.id}" aria-label="แสดง ${s.label}" ${p.visible?'checked':''}><span class="switch"></span></label></div>`;}).join('')}</div><p id="shortcut-drag-help" class="sr-only">ลากจุดจับเพื่อเรียงลำดับ หรือกด Space เพื่อเลือก ใช้ปุ่มลูกศรบนแป้นพิมพ์เพื่อย้าย กด Space อีกครั้งเพื่อวาง หรือ Escape เพื่อยกเลิก</p><span id="shortcut-reorder-live" class="sr-only" role="status" aria-live="polite"></span><p id="shortcut-feedback" class="small ${prefsChanged()?'':'muted'} space" role="status">${prefsChanged()?'มีการเปลี่ยนแปลงที่ยังไม่บันทึก · ยกเลิกจะคืนค่าที่บันทึกไว้':'ตรงกับเมนูที่บันทึกไว้'}</p><div class="form-actions">${btn('ยกเลิก','cancel-preferences')}${btn('บันทึก','save-preferences',{primary:true,disabled:!prefsChanged()})}</div>`)}${panel('ตัวอย่างเมนูลัด',`<div class="shortcut-grid shortcut-preview">${prefDraft.filter(p=>p.visible).map(p=>actionCard(shortcuts.find(s=>s.id===p.id))).join('')||'<p class="muted">ซ่อนเมนูลัดทั้งหมด</p>'}</div><p class="small muted space">การลงเวลาหลักยังอยู่บนหน้าวันนี้เสมอ</p>`)}</div>`;}
function announcementRow(a){return `<a class="list-link" href="#announcement/${a.id}"><div class="list-row">${pad('megaphone')}<div class="grow"><h3>${a.pinned?icon('info'):''}${esc(a.title)}</h3><div class="sub">${esc(a.author)} · ${dateLabel(a.date,true)}</div></div>${tag(a.read?'อ่านแล้ว':'ยังไม่อ่าน',a.read?'':'blue',a.read?'check':'info')}${icon('chevron')}</div></a>`;}
function announcements(){return heading('ประกาศ','ข่าวสารที่เผยแพร่สำหรับสำนักงานใหญ่','megaphone')+panel('',state.announcements.map(announcementRow).join(''));}
function announcementDetail(id){const a=state.announcements.find(x=>x.id===id);if(!a)return stateView('empty');a.read=true;return heading('ประกาศ',esc(a.author),'megaphone',link('กลับประกาศ','announcements','back'))+panel('',`<div class="row wrap">${tag('อ่านแล้ว','success','check')}${a.pinned?tag('ปักหมุด','blue','info'):''}<span class="small muted">${dateLabel(a.date)}</span></div><article class="article space"><h1>${esc(a.title)}</h1>${a.body.split('\n\n').map(p=>`<p class="space">${esc(p).replace(/\n/g,'<br>')}</p>`).join('')}</article><div class="view-footer">สำหรับสำนักงานใหญ่ · เวอร์ชัน 1 · สถานะอ่านสำหรับพนักงานตัวอย่างคนนี้</div>`);}
function notifications(){return heading('การแจ้งเตือน',`${unreadCount()} รายการยังไม่อ่าน`,'bell',btn('อ่านทั้งหมด','read-all',{disabled:!unreadCount(),icon:'check'}))+panel('',state.notifications.map(n=>`<button class="action-card list-row" data-action="open-notification" data-id="${n.id}" style="border-radius:12px;margin-top:10px">${pad('bell')}<div class="grow"><div class="label">${esc(n.title)}</div><div class="sub">${esc(n.sub)}</div></div>${tag(n.read?'อ่านแล้ว':'ยังไม่อ่าน',n.read?'':'blue')}${icon('chevron')}</button>`).join('')||stateView('empty'));}
function payslipRow(p){return `<a class="list-link" href="#payslip/${p.id}"><div class="list-row">${pad('wallet')}<div class="grow"><h3>${new Intl.DateTimeFormat('th-TH',{month:'long',year:'numeric',timeZone:'UTC'}).format(date(p.year+'-'+String(p.month).padStart(2,'0')+'-01'))}</h3><div class="sub">จ่าย ${dateLabel(p.payDate,true)} · เวอร์ชัน ${p.version}</div></div>${tag('เผยแพร่แล้ว','success','check')}${icon('chevron')}</div></a>`;}
function payslips(){return heading('สลิปเงินเดือน','เอกสารที่ฝ่าย HR เผยแพร่ให้คุณ','wallet')+panel('',`<div class="filterbar"><div class="field"><label for="payslip-year">ปี</label><select id="payslip-year"><option value="2026" ${payslipYear==='2026'?'selected':''}>2569 (2026)</option><option value="2025" ${payslipYear==='2025'?'selected':''}>2568 (2025)</option></select></div><span class="small muted">${state.payslips.filter(p=>String(p.year)===payslipYear).length} งวด</span></div>${state.payslips.filter(p=>String(p.year)===payslipYear).sort((a,b)=>b.month-a.month).map(payslipRow).join('')||stateView('empty',{recovery:btn('ดูสลิปปี 2569','recover-payslips',{primary:true})})}`);}
function payslipDetail(id){const p=state.payslips.find(x=>x.id===id);if(!p)return stateView('empty');const show=verified(id);const amount=n=>show?money(n):'<span class="privacy-mask">฿••••••</span>';return heading('สลิปเงินเดือน',`${dateLabel(p.year+'-'+String(p.month).padStart(2,'0')+'-01')} · เวอร์ชัน ${p.version}`,'wallet',link('กลับรายการ','payslips','back'))+`<div class="cols"><div class="stack">${panel('รายละเอียด',`<dl class="data-list"><dt>ผู้รับ</dt><dd>มินตรา · EMP-DEMO-01</dd><dt>งวด</dt><dd>${p.month}/${p.year+543}</dd><dt>วันที่จ่าย</dt><dd>${dateLabel(p.payDate)}</dd><dt>การจ่าย</dt><dd>รายเดือน</dd><dt>แหล่งข้อมูล</dt><dd>ข้อมูลนำเข้าสมมติ · v${p.version}</dd></dl>`)}${panel('เงินได้และเงินหัก',`${notice(show?'แสดงยอดแล้ว · การยืนยันตัวอย่างมีอายุ 60 วินาที':'ยอดเงินถูกซ่อนไว้ เปิดดูเมื่อพร้อม')}<div class="list-row space"><strong class="grow">เงินเดือน</strong><span class="payslip-amount" data-pay-amount>${amount(p.base)}</span></div><div class="list-row"><span class="grow">ค่าโอทีจากเอกสารนำเข้า</span><span class="payslip-amount">${amount(p.ot)}</span></div><div class="list-row"><span class="grow">เงินได้อื่น</span><span class="payslip-amount">${amount(p.other)}</span></div><div class="list-row"><strong class="grow">รวมเงินได้</strong><span class="payslip-amount">${amount(sumBaht(p.base,p.ot,p.other))}</span></div><div class="list-row"><span class="grow">เงินหักตามเอกสาร</span><span class="payslip-amount">${amount(p.deduction)}</span></div><div class="pay-total row between"><span>เงินได้สุทธิ</span><span class="mono">${amount(sumBaht(p.base,p.ot,p.other,-p.deduction))}</span></div><div class="form-actions">${btn(show?'ซ่อนยอด':'เปิดดูยอด',show?'hide-pay':'reveal-pay',{icon:show?'eyeoff':'eye',extra:`data-id="${id}"`})}${btn('ดาวน์โหลดตัวอย่าง','download-pay',{primary:true,icon:'download',extra:`data-id="${id}"`})}</div>`)} </div>${panel('ความเป็นส่วนตัว',`<div class="row">${pad('shield')}<h3>ยืนยันผ่านบัญชีของคุณ</h3></div><p class="muted space">ระบบจริงจะใช้การยืนยันที่ผู้ให้บริการบัญชีรองรับก่อนส่งยอดเงินหรือเอกสารที่ได้รับสิทธิ์</p><p class="small muted space">แบบนี้จำลองการยืนยันโดยไม่รับรหัสผ่านหรือ PIN และใช้ข้อมูลเงินเดือนสมมติในไฟล์ HTML เท่านั้น</p><p class="small muted space">การเปลี่ยนหน้า ซ่อนยอด หรือหมดเวลา จะปิดการแสดงยอด</p>`)}</div>`;}
function profile(){return heading('โปรไฟล์ของคุณ','ข้อมูลการจ้างงานที่ฝ่าย HR ดูแล','user')+panel('มินตรา · EMP-DEMO-01',`<dl class="data-list"><dt>สถานะ</dt><dd>${tag('ทำงานอยู่','success','check')}</dd><dt>สถานที่</dt><dd>สำนักงานใหญ่</dd><dt>หัวหน้างาน</dt><dd>ภัทรา</dd><dt>ตารางงาน</dt><dd>จันทร์–ศุกร์ · 08:30–17:30</dd><dt>ช่วงพัก</dt><dd>60 นาที</dd><dt>วันเริ่มงาน</dt><dd>1 มกราคม 2569 (ตัวอย่าง)</dd></dl><div class="space">${notice('ข้อมูลนี้อ่านอย่างเดียว หากข้อมูลไม่ถูกต้อง ติดต่อผู้ดูแล HR')}</div>`);}
function reviewPage(){const selected=state.requests.find(x=>x.id===routeInfo().id)||state.requests.find(x=>x.status==='PENDING');const queue=state.requests.filter(r=>r.status==='PENDING');return heading('พิจารณาคำขอ',esc(persona().name)+' · คำขอของผู้ใต้บังคับบัญชาในสำนักงานใหญ่','shield')+`<div class="cols"><div class="stack">${panel('รอพิจารณา '+queue.length+' รายการ',queue.length?queue.map(r=>`<a class="list-link" href="#review/${r.id}"><div class="list-row">${pad(r.type==='correction'?'clock':'leaf')}<div class="grow"><h3>มินตรา · ${r.title}</h3><div class="sub">${dateLabel(r.from,true)}${r.units?' · '+r.units+' วัน':''}</div></div>${status(r.status)}${icon('chevron')}</div></a>`).join(''):notice('พิจารณาคำขอครบแล้ว · ไม่มีรายการรอพิจารณา','success','check'))}${notice('ผู้พิจารณาตัวอย่างเป็นคนละคนกับผู้ขอ · ระบบจริงต้องบังคับขอบเขตสิทธิ์ที่ API<br>งวดที่ปิดแล้วอ่านได้ การแก้ไขต้องผ่าน revision ของงวด')}</div>${selected?panel(selected.title,`${status(selected.status)}<dl class="data-list space"><dt>ผู้ขอ</dt><dd>มินตรา · EMP-DEMO-01</dd><dt>ช่วงวัน</dt><dd>${dateLabel(selected.from,true)} – ${dateLabel(selected.to,true)}</dd><dt>เหตุผล</dt><dd>${esc(selected.reason)}</dd>${selected.type==='correction'?correctionEvidence(selected):`<dt>วันที่คิดสิทธิ์</dt><dd>${selected.units} วัน</dd><dt>ยอดที่สำรอง</dt><dd>${selected.status==='PENDING'?selected.units:0} วัน</dd><dt>นโยบาย</dt><dd>ตัวอย่าง v1 · ปี 2569</dd>`}</dl>${selected.status==='PENDING'?`<div class="form-actions">${btn('ส่งกลับแก้ไข','return-request',{extra:`data-id="${selected.id}"`})}${btn('รับรองคำขอ','approve-request',{primary:true,icon:'check',extra:`data-id="${selected.id}"`})}</div>`:notice('รายการนี้พิจารณาแล้ว เลือกรายการถัดไปได้','success','check')}`):panel('ไม่มีคำขอรอพิจารณา','<p class="muted">ทุกคำขอได้รับการพิจารณาแล้ว</p>')}</div>`;}
/* One scheduled future version (v2). Saving persists it and the form keeps showing the saved values; v1 and the 2569 balances never change. */
function policy(){const current=state.policyVersions[0],next=state.policyVersions[1];const f=next||{...current,effective:'2027-01-01'};const halfText=v=>v?'รองรับ':'ไม่รองรับ';return heading('นโยบายการลา','ตั้งนโยบายใหม่ตามวันที่มีผล โดยคงประวัติเดิม','settings')+`<div class="cols">${panel(next?'ฉบับถัดไป v2 (บันทึกแล้ว)':'ฉบับถัดไป v2',`${next?notice(`บันทึกนโยบายตัวอย่าง v${next.version} แล้ว · มีผล ${esc(dateLabel(next.effective))} · บันทึกครั้งที่ ${next.revision}<br>ฟอร์มแสดงค่าที่บันทึกไว้ แก้และบันทึกอีกครั้งเพื่อปรับฉบับเดียวกันก่อนวันที่มีผล`,'success','check'):''}<form id="policy-form" class="${next?'space':''}"><div class="field"><label for="policy-name">ชื่อนโยบาย *</label><input id="policy-name" name="name" required maxlength="80" value="${esc(f.name)}"></div><div class="field"><label for="policy-effective">มีผลตั้งแต่ *</label><input id="policy-effective" name="effective" type="date" required min="2027-01-01" max="2027-12-31" value="${esc(f.effective)}"><span class="hint">ต้องอยู่ในปี 2570 · ไม่คำนวณปี 2569 ย้อนหลัง</span></div><div class="half"><div class="field"><label for="policy-annual">ลาพักร้อน (วัน) *</label><input id="policy-annual" name="annual" type="number" min="0" max="365" step="0.5" required value="${esc(f.annual)}"></div><div class="field"><label for="policy-carry">ยกยอดได้สูงสุด (วัน) *</label><input id="policy-carry" name="carry" type="number" min="0" max="365" step="0.5" required value="${esc(f.carry)}"><span class="hint">ไม่เกินสิทธิ์ลาพักร้อนของฉบับนี้</span></div></div><label class="control-check"><input type="checkbox" name="half" ${f.half?'checked':''}>รองรับครึ่งวัน (ปิดแล้วต้องเป็นจำนวนวันเต็ม)</label><div id="form-error" role="alert"></div><div class="form-actions">${btn(next?'บันทึกการแก้ไข v2':'บันทึกฉบับใหม่',null,{primary:true,submit:true})}</div></form>`)}${panel('ฉบับนโยบาย',`<h3>ตัวอย่าง v1 · ใช้อยู่ · ปี 2569</h3><dl class="data-list space"><dt>ลาพักร้อน</dt><dd>${esc(current.annual)} วัน</dd><dt>ยกยอด</dt><dd>${esc(current.carry)} วัน</dd><dt>ครึ่งวัน</dt><dd>${halfText(current.half)}</dd><dt>ลากิจ / ลาป่วย</dt><dd>3 / 30 วัน</dd><dt>คำขอรอพิจารณา</dt><dd>สำรองสิทธิ์</dd></dl>${next?`<h3 class="space">v2 · กำหนดมีผล ${esc(dateLabel(next.effective))}</h3><dl class="data-list space" data-policy-saved><dt>ชื่อ</dt><dd>${esc(next.name)}</dd><dt>ลาพักร้อน</dt><dd>${esc(next.annual)} วัน</dd><dt>ยกยอด</dt><dd>${esc(next.carry)} วัน</dd><dt>ครึ่งวัน</dt><dd>${halfText(next.half)}</dd></dl>`:''}<div class="space">${notice('ตัวเลขเป็นนโยบายสมมติ ไม่ใช่ค่าขั้นต่ำตามกฎหมาย<br>ฉบับใหม่ไม่คำนวณยอดปี 2569 ย้อนหลัง')}</div>`)}</div>`;}
function publishing(){return heading('จัดการประกาศ','ร่าง ตรวจกลุ่มผู้รับ และเผยแพร่','megaphone')+`<div class="cols">${panel('ประกาศใหม่',`<form id="publish-form"><div class="field"><label for="announcement-title">หัวข้อ *</label><input id="announcement-title" name="title" required placeholder="เขียนหัวข้อให้ชัดเจน"></div><div class="field"><label for="announcement-body">เนื้อหา *</label><textarea id="announcement-body" name="body" required placeholder="รายละเอียดที่พนักงานต้องทราบ"></textarea></div><div class="field"><label for="announcement-audience">ผู้รับ</label><select id="announcement-audience" name="audience"><option value="hq">พนักงานสำนักงานใหญ่</option></select></div><div class="field"><label for="announcement-date">วันเผยแพร่</label><input id="announcement-date" name="date" type="date" value="2026-10-12" max="2026-10-12" required><span class="hint">แบบนี้เผยแพร่ทันที ไม่จำลองการตั้งเวลาในอนาคต</span></div><label class="control-check"><input name="pinned" type="checkbox">ปักหมุด</label><div id="form-error" role="alert"></div><div class="form-actions">${btn('บันทึกร่าง','save-draft')}${btn('เผยแพร่ในตัวอย่าง',null,{primary:true,submit:true})}</div></form>`)}<div class="stack">${panel('ร่างที่บันทึกไว้',state.drafts.length?state.drafts.map(d=>`<div class="list-row"><div class="grow"><h3>${esc(d.title)}</h3><div class="sub">สำนักงานใหญ่ · ยังไม่เผยแพร่${loadedDraft===d.id?' · เปิดอยู่ในฟอร์ม':''}</div></div>${btn('เปิดร่าง','load-draft',{extra:`data-id="${d.id}"`})}</div>`).join(''):'<p class="muted">ยังไม่มีร่าง</p>')}${panel('เผยแพร่แล้ว',state.announcements.map(announcementRow).join(''))}</div></div>`;}
const importHeader='employeeId,base,ot,other,deduction';
const importSample=importHeader+'\nEMP-DEMO-01,28000,1500,500,800\nEMP-UNKNOWN,28000,0,0,800\n';
function validateImport(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean);if(lines.shift()!==importHeader)throw new Error('หัวตารางต้องเป็น '+importHeader);if(!lines.length||lines.length>100)throw new Error('รองรับ 1–100 แถวในตัวอย่าง');const seen=new Set();return lines.map((line,i)=>{const parts=line.split(',').map(part=>part.trim());const [employeeId,...values]=parts;const [base,ot,other,deduction]=values.map(v=>v===''?NaN:Number(v));const errors=[];if(parts.length!==5)errors.push('คอลัมน์ไม่ครบ');if(employeeId!=='EMP-DEMO-01')errors.push('ไม่พบรหัสพนักงาน');if(seen.has(employeeId))errors.push('รหัสซ้ำในไฟล์');seen.add(employeeId);const amountsOk=values.length===4&&values.every(v=>/^\d{1,9}(\.\d{1,2})?$/.test(v));if(!amountsOk)errors.push('ยอดต้องเป็นจำนวนบวกหรือศูนย์ ทศนิยมไม่เกิน 2 ตำแหน่ง');else if(sumBaht(base,ot,other,-deduction)<0)errors.push('เงินสุทธิติดลบ');return {row:i+2,employeeId,base,ot,other,deduction,errors,selected:true};});}
/* Staged rows are bound to the period chosen when they were checked. Any replacement read clears them first. */
function importPage(){const rows=state.importRows,selected=rows.filter(r=>r.selected),invalid=selected.filter(r=>r.errors.length);const periodOk=/^202[67]-(0[1-9]|1[0-2])$/.test(importPeriod);const label=periodOk?monthLabel(importPeriod.slice(0,4),Number(importPeriod.slice(5))):'';const duplicate=periodOk&&state.payslips.some(p=>periodKey(p.year,p.month)===importPeriod);const done=state.importDone;const amount=(...v)=>{const n=sumBaht(...v);return Number.isFinite(n)?money(n):'—';};
return heading('นำเข้าสลิปเงินเดือน','ตรวจรหัสพนักงานและยอดก่อนเผยแพร่เอกสารนำเข้า','upload')+panel('1 · เลือกงวดและไฟล์',`<div class="filterbar"><div class="field"><label for="import-period">งวด</label><input id="import-period" type="month" value="${esc(importPeriod)}" min="2026-01" max="2027-12"></div>${btn('ดาวน์โหลด CSV ตัวอย่าง','import-template',{icon:'download'})}${btn('โหลดข้อมูลตัวอย่าง','load-import',{icon:'file'})}</div><div class="field"><label for="import-file">ไฟล์ CSV (ไม่เกิน 100 KB)</label><input id="import-file" type="file" accept=".csv,text/csv"><span class="hint">${importHeader} · จัดเก็บในหน้านี้เท่านั้น · เปลี่ยนงวดจะล้างแถวที่ตรวจไว้</span></div>${periodOk?'':notice('เลือกงวดระหว่าง ม.ค. 2569 ถึง ธ.ค. 2570','error','alert')}<div id="import-error" role="alert">${state.importError?notice(`<strong>นำเข้าไม่สำเร็จ · ${esc(state.importSource)}</strong><br>${esc(state.importError)}<br>ล้างแถวที่ตรวจไว้ก่อนหน้าแล้ว ยังไม่มีแถวที่จะเผยแพร่`,'error','alert'):''}</div>`)+panel('2 · ตรวจและเลือกแถว',`${done?notice(`เผยแพร่เอกสารตัวอย่างแล้ว · งวด ${esc(monthLabel(done.period.slice(0,4),Number(done.period.slice(5))))} · เวอร์ชัน 1 · ${done.count} แถว<br>แถวที่ไม่เลือกหรือไม่ผ่านไม่ถูกเผยแพร่ และยังแสดงไว้ให้ตรวจสอบ`,'success','check'):''}${state.importReading?`<p class="muted" role="status">กำลังตรวจ ${esc(state.importSource)}…</p>`:rows.length?`<p class="small muted">ไฟล์: ${esc(state.importSource)} · ตรวจสำหรับงวด ${esc(label)}</p><div class="table-wrap space"><table><thead><tr><th>เลือก</th><th>พนักงาน</th><th>เงินได้</th><th>เงินหัก</th><th>สุทธิ</th><th>ผลตรวจ</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${r.selected?'':'excluded'}"><td><label class="control-check"><input type="checkbox" data-import-row="${i}" aria-label="เลือกแถว ${r.row} ${esc(r.employeeId)}" ${r.selected?'checked':''}><span class="small">${r.selected?(r.errors.length?'<strong class="text-danger">เลือกอยู่ · ต้องไม่เลือก</strong>':'จะเผยแพร่'):'ไม่รวม · ไม่เผยแพร่'}</span></label></td><td>${esc(r.employeeId)}<div class="small muted">แถว ${r.row}</div></td><td>${amount(r.base,r.ot,r.other)}</td><td>${amount(r.deduction)}</td><td>${amount(r.base,r.ot,r.other,-r.deduction)}</td><td>${r.errors.length?tag('ไม่ผ่าน','danger','alert')+'<div class="small">'+r.errors.map(esc).join('<br>')+'</div>':tag('ผ่าน','success','check')}</td></tr>`).join('')}</tbody></table></div><div class="space">${notice(`เลือก ${selected.length} แถว · ผ่าน ${selected.length-invalid.length} · ไม่ผ่าน ${invalid.length} · ไม่รวม ${rows.length-selected.length}<br>จะเผยแพร่งวด ${esc(label||'—')} · เวอร์ชัน 1 เฉพาะแถวที่เลือก และทุกแถวที่เลือกต้องผ่าน`,invalid.length?'warning':'','info')}</div>${duplicate?`<div class="compact">${notice('งวดนี้มีเอกสารเผยแพร่แล้ว ตัวอย่างไม่อนุญาตเขียนทับ เลือกงวดใหม่','error','alert')}</div>`:''}<div class="form-actions">${btn(`เผยแพร่ ${selected.length} แถว · ${label||'—'}`,'publish-import',{primary:true,disabled:!periodOk||state.importFor!==importPeriod||!selected.length||!!invalid.length||duplicate})}</div>`:'<p class="muted">เลือกงวด แล้วเลือกไฟล์หรือโหลดข้อมูลตัวอย่างเพื่อเริ่มตรวจ</p>'}`);}
const boards=[['components/01-action-card.png','01 · Action Card ที่ใช้ร่วมกัน','component-01'],['components/02-summary-contexts.png','02 · ข้อมูลสรุปและสิทธิ์ลา','component-02'],['components/03-request-contexts.png','03 · รายการคำขอและสถานะ','component-03'],['components/04-customization-states.png','04 · การปรับเมนูและสถานะ','component-04'],['pages/01-home.png','05 · Employee home','page-01'],['pages/02-attendance.png','06 · Attendance summary & correction','page-02'],['pages/03-requests.png','07 · My requests','page-03'],['pages/04-leave.png','08 · Leave balance & request','page-04'],['pages/05-holidays.png','09 · Annual holidays','page-05'],['pages/06-communications.png','10 · Announcements & notifications','page-06'],['pages/07-payslips.png','11 · Payslip list & masked detail','page-07'],['pages/08-payslip-states.png','12 · Reveal & verification','page-08'],['pages/09-review-policy.png','13 · Review & leave policy','page-09'],['pages/10-publishing-import.png','14 · Publishing & payslip import','page-10']];
function gallery(){return heading('ภาพออกแบบ','Image generation · 4 ภาพส่วนประกอบร่วม + 10 ภาพหน้าจอ','image')+notice('ภาพเป็นแนวทางองค์ประกอบ ส่วนข้อความ สี และตัวเลขที่ตรวจแก้แล้วอยู่ใน HTML preview นี้')+`<div class="gallery-grid space">${boards.map(([path,label,prompt])=>`<div class="gallery-card"><figure><a href="../images/${path}" target="_blank" rel="noopener"><img src="../images/${path}" alt="ภาพออกแบบ ${label}" loading="lazy"></a><figcaption><h3>${label}</h3><div class="row wrap compact"><a class="btn" href="../images/${path}" target="_blank" rel="noopener">เปิดภาพเต็ม ${icon('image')}</a><a class="btn" href="../prompts/${prompt}.txt" target="_blank" rel="noopener">ดู prompt</a></div></figcaption></figure></div>`).join('')}</div>`;}
function components(){return heading('Action Card','ส่วนประกอบเดียว หลายบริบท · สีจากระบบปัจจุบัน','box')+`<div class="sample-lanes">${panel('เมนูลัด',`<div class="shortcut-grid">${shortcuts.slice(0,4).map(actionCard).join('')}</div>`)}${panel('รายการคำขอ',state.requests.slice(0,2).map(requestRow).join(''))}${panel('ข้อมูลสรุป',`<div class="half">${['WORKED','LEAVE'].map(code=>`<a class="action-card metric" href="#attendance">${pad(code==='WORKED'?'check':'leaf')}<div><div class="label">${kindLabels[code]}</div><strong>${state.days.filter(d=>d.kind===code).length}</strong><div class="sub">วัน</div></div></a>`).join('')}</div>`)}${panel('สถานะส่วนประกอบ',`<a class="action-card" aria-current="page" href="#components">${pad('check')}<div><div class="label">เลือกอยู่</div><div class="sub">ใช้ข้อความและเส้นขอบร่วมกัน</div></div></a><button class="action-card compact" disabled aria-disabled="true">${pad('file')}<div><div class="label">ยังไม่พร้อมใช้งาน</div><div class="sub">ตัวอย่างสถานะปิดใช้งาน</div></div></button><p class="small muted space">ลอง Tab เพื่อดูเส้นโฟกัส และปุ่มสลับธีมด้านบน</p>`)}</div><div class="space">${link('ดูภาพส่วนประกอบทั้ง 4 ภาพ','gallery','image')}</div>`;}
function planPage(){return heading('แผนส่งมอบ HR','เริ่มจาก self-service และรักษาความถูกต้องของ attendance','file')+notice('<strong>สถานะ:</strong> ภาพออกแบบและ HTML preview สำหรับตรวจงาน ฟีเจอร์ใหม่ยังไม่ใช้กับข้อมูลจริง')+`<div class="space">${panel('ลำดับการพัฒนา',`<ol class="timeline"><li><strong>A · Home + Employee holidays</strong><small>ประกอบ Today เดิมกับ Action Card และ annual holiday query ที่ตรวจสิทธิ์</small></li><li><strong>B · Attendance summary + My requests</strong><small>สรุปวันอย่างสอดคล้อง รักษา punch เดิม correction และงวดปิด</small></li><li><strong>C · Leave + Reviewer + Policy</strong><small>สิทธิ์ สำรองยอด ledger และการรับรองใน transaction เดียว</small></li><li><strong>D · Announcements + Notifications + Preferences</strong><small>กลุ่มผู้รับ ประวัติอ่าน event และ badge ที่นับจากข้อมูลจริง</small></li><li><strong>E · Imported payslips + Supported verification</strong><small>ตรวจไฟล์ เผยแพร่ตามพนักงาน เวอร์ชัน และ protected download</small></li></ol>`)}${panel('เอกสารและหลักฐาน',`<div class="row wrap"><a class="btn primary" href="../plan.md" target="_blank" rel="noopener">แผนเต็ม ${icon('file')}</a><a class="btn" href="../review/kiro-review.md" target="_blank" rel="noopener">ผลตรวจ Kiro</a><a class="btn" href="../review/final-review.md" target="_blank" rel="noopener">ผลตรวจสุดท้าย</a>${link('ภาพออกแบบ','gallery','image')}</div><p class="muted small space">เอกสารระบุขอบเขต API/ข้อมูล เกณฑ์รับงาน ลำดับส่งมอบ และเรื่องที่ต้องกำหนดนโยบายก่อนเริ่มระบบจริง</p>`)}</div>`;}
const viewFns={home,attendance,day:dayDetail,correction:correctionForm,requests,request:requestDetail,leave,'leave-new':leaveForm,holidays:holidaysPage,customize,announcements,announcement:announcementDetail,notifications,payslips,payslip:payslipDetail,profile,review:reviewPage,policy,publish:publishing,import:importPage,components,gallery,plan:planPage};
function render(){if(shortcutDrag)finishShortcutDrag(false,false);const {page,id}=routeInfo();if(page!=='payslip'||activeSlip!==id){clearVerification();activeSlip=page==='payslip'?id:'';}const content=restricted(page)?stateView('denied'):responseState!=='normal'?stateView(responseState,{recovery:btn(responseState==='error'?'ลองอีกครั้ง':'กลับสู่หน้าปกติ','normal',{primary:true})}):(viewFns[page]||home)(id);$('#app').innerHTML=shell(content);$('#response').value=responseState;updateCharge();document.title=(titles[page]||'วันนี้')+' · HR design preview';}
function allowDiscard(){if(!dirty)return true;if(confirm('คุณมีข้อมูลที่ยังไม่บันทึก ต้องการออกจากหน้านี้หรือไม่?')){dirty=false;return true;}return false;}
function formError(message){const target=$('#form-error');if(target){target.innerHTML=notice(esc(message),'error','alert');target.scrollIntoView({block:'nearest',behavior:'smooth'});}}
function addNotification(title,sub,target){state.notifications.unshift({id:nextId('n'),title,sub,target,read:false});}
function reviewDecision(id,outcome,reason=''){if(!allowRole('supervisor','hr'))return;const r=state.requests.find(x=>x.id===id);if(!r||r.status!=='PENDING'){toast('คำขอนี้พิจารณาแล้ว ไม่บันทึกซ้ำ');render();return;}r.status=outcome;r.returnReason=outcome==='RETURNED'?reason:'';r.history.push([outcome==='CERTIFIED'?'รับรองแล้ว':'ส่งกลับแก้ไข','12 ต.ค. 2569 · ตัวอย่าง',persona().name+(reason?' · '+reason:'')]);if(outcome==='CERTIFIED'&&r.type==='correction'){/* Effective value changes; the recorded original punch is kept. */const d=state.days.find(x=>x.day===r.from);if(d){d.end=r.proposed;d.kind='WORKED';}}addNotification(`คำขอ${r.title} ${outcome==='CERTIFIED'?'รับรองแล้ว':'ส่งกลับแก้ไข'}`,reason||'ดูผลพิจารณาและยอดที่เกี่ยวข้อง','request/'+id);toast('บันทึกผลพิจารณาในตัวอย่างแล้ว');render();}
function verifyDialog(id,downloadAfter=false){openDialog('ยืนยันเพื่อเปิดดูสลิป',`<div class="row">${pad('shield')}<div><strong>ยืนยันผ่านบัญชี</strong><p class="small muted">งวดนี้เท่านั้น · มีอายุ 60 วินาที</p></div></div><p class="space">ระบบจริงจะเรียกการยืนยันของผู้ให้บริการบัญชี ก่อนส่งข้อมูลที่ได้รับสิทธิ์</p>${notice('ปุ่มนี้จำลองการยืนยัน ไม่รับรหัสผ่านหรือ PIN')}<div class="form-actions">${btn('ยกเลิก','close-dialog')}${btn('จำลองการยืนยัน','verify-pay',{primary:true,extra:`data-id="${id}" data-download="${downloadAfter?'yes':'no'}"`})}</div>`);}
function payDownload(id){const p=state.payslips.find(x=>x.id===id);if(!p)return;if(!verified(id)){verifyDialog(id,true);return;}const body=`<!doctype html><html lang="th"><meta charset="utf-8"><title>สลิปเงินเดือนตัวอย่าง ${p.month}/${p.year+543}</title><style>body{font-family:system-ui,sans-serif;max-width:700px;margin:40px auto;padding:24px;color:#17212f}td,th{padding:12px;border-bottom:1px solid #ddd;text-align:left}table{width:100%;border-collapse:collapse}h1{color:#1d4ed8}</style><h1>เอกสารตัวอย่าง · ไม่มีผลทางการเงิน</h1><p>มินตรา · EMP-DEMO-01 · งวด ${p.month}/${p.year+543} · เวอร์ชัน ${p.version}</p><p>วันที่จ่าย ${esc(dateLabel(p.payDate))}</p><table><tr><th>รายการ</th><th>จำนวน</th></tr>${[['เงินเดือน',p.base],['ค่าโอทีจากเอกสาร',p.ot],['เงินได้อื่น',p.other],['รวมเงินได้',sumBaht(p.base,p.ot,p.other)],['เงินหัก',p.deduction],['เงินได้สุทธิ',sumBaht(p.base,p.ot,p.other,-p.deduction)]].map(([k,n])=>`<tr><td>${k}</td><td>${money(n)}</td></tr>`).join('')}</table><p>ข้อมูลสมมติจาก HTML preview · ใช้คำสั่ง Print ของเบราว์เซอร์เพื่อบันทึกเป็น PDF</p></html>`;download(`DEMO-payslip-${p.year}-${p.month}-v${p.version}.html`,body,'text/html;charset=utf-8');toast('ดาวน์โหลดเอกสารตัวอย่างแล้ว');}
function draftData(){const form=$('#publish-form');if(!form)return null;const d=Object.fromEntries(new FormData(form));return {...d,title:d.title.trim(),body:d.body.trim(),pinned:d.pinned==='on'};}
async function doAction(el){const action=el.dataset.action,id=el.dataset.id;
  if(action==='close-dialog'){closeDialog();return;}
  if(action==='menu'){setMenu(true);return;}
  if(action==='close-menu'){setMenu(false);return;}
  if(action==='theme'){document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';el.innerHTML=icon(document.documentElement.dataset.theme==='dark'?'sun':'moon');return;}
  if(action==='normal'){responseState='normal';render();return;}
  if(action==='recover-requests'){filter='all';query='';render();return;}
  if(action==='recover-holidays'){holidayYear='2026';render();return;}
  if(action==='recover-payslips'){payslipYear='2026';render();return;}
  if(action==='reset'){if(!allowDiscard())return;clearVerification();closeDialog();localStorage.removeItem(prefsKey);state=initial();importToken++;prefDraft=null;loadedDraft='';filter='all';query='';holidayYear='2026';payslipYear='2026';attendanceKind='all';responseState='normal';importPeriod='2026-10';render();toast('เริ่มข้อมูลตัวอย่างใหม่แล้ว');return;}
  if(action==='clock'){if(!allowRole('employee')||state.clockBusy||state.days.at(-1).end)return;const snapshot=state;state.clockBusy=true;render();await new Promise(resolve=>setTimeout(resolve,400));if(state!==snapshot)return;const today=state.days.at(-1);/* A clock-out is a recorded original punch as well as the effective value. */today.end='17:30';today.originalEnd='17:30';today.kind='WORKED';state.clockBusy=false;state.receipt=true;render();toast('บันทึกเวลาออกในตัวอย่างแล้ว');return;}
  if(action==='attendance-filter'){attendanceKind=el.dataset.kind;render();return;}
  if(action==='create-request'){if(!allowRole('employee'))return;openDialog('สร้างคำขอ',`<div class="stack"><a class="action-card" href="#leave-new" data-dismiss-dialog>${pad('leaf')}<div><div class="label">ขอลา</div><div class="sub">เลือกวันและตรวจยอดสิทธิ์</div></div>${icon('chevron')}</a><a class="action-card" href="#attendance" data-dismiss-dialog>${pad('clock')}<div><div class="label">ขอแก้ไขเวลา</div><div class="sub">เลือกวันที่ต้องการจากประวัติ</div></div>${icon('chevron')}</a></div>`);return;}

  if(action==='save-preferences'){if(!allowRole('employee')||!prefsChanged())return;state.preferences=structuredClone(prefDraft);try{localStorage.setItem(prefsKey,JSON.stringify(state.preferences));}catch{toast('บันทึกในหน้านี้แล้ว แต่เบราว์เซอร์ไม่อนุญาตเก็บหลังโหลดใหม่');}dirty=false;prefDraft=null;location.hash='home';toast('บันทึกเมนูลัดแล้ว');return;}
  if(action==='cancel-preferences'){/* Cancel explicitly discards the draft and keeps the saved order. */dirty=false;prefDraft=null;location.hash='home';return;}
  if(action==='read-all'){if(!allowRole('employee'))return;state.notifications.forEach(n=>n.read=true);render();toast('อ่านการแจ้งเตือนทั้งหมดแล้ว');return;}
  if(action==='open-notification'){if(!allowRole('employee'))return;const n=state.notifications.find(x=>x.id===id);if(n){if(!allowDiscard())return;n.read=true;location.hash=n.target;}return;}
  if(action==='reveal-pay'){if(!allowRole('employee'))return;verifyDialog(id);return;}
  if(action==='verify-pay'){const {page,id:current}=routeInfo();if(!allowRole('employee')||!state.payslips.some(p=>p.id===id)||page!=='payslip'||current!==id){closeDialog();return;}setVerification(id);dialogFocus='[data-action="hide-pay"]';closeDialog();render();if(el.dataset.download==='yes')payDownload(id);return;}
  if(action==='hide-pay'){clearVerification();render();return;}
  if(action==='download-pay'){if(!allowRole('employee'))return;payDownload(id);return;}
  if(action==='approve-request'){reviewDecision(id,'CERTIFIED');return;}
  if(action==='return-request'){if(!allowRole('supervisor','hr'))return;if(state.requests.find(x=>x.id===id)?.status!=='PENDING'){reviewDecision(id,'RETURNED');return;}openDialog('ส่งกลับแก้ไข',`<form id="return-form" data-request="${id}"><div class="field"><label for="return-reason">เหตุผล *</label><textarea id="return-reason" name="reason" required placeholder="ระบุสิ่งที่พนักงานต้องแก้ไข"></textarea></div><div id="form-error" role="alert"></div><div class="form-actions">${btn('ยกเลิก','close-dialog')}${btn('ส่งกลับแก้ไข',null,{submit:true,primary:true})}</div></form>`);return;}
  if(action==='holiday-csv'){const rows=holidays.filter(h=>h.date.startsWith(holidayYear));download(`DEMO-holidays-${holidayYear}.csv`,csv([['date','name','site'],...rows.map(h=>[h.date,h.name,'สำนักงานใหญ่'])]),'text/csv;charset=utf-8');return;}
  if(action==='attendance-csv'){if(!allowRole('employee'))return;download('DEMO-attendance-2026-10.csv',csv([['date','start','originalEnd','effectiveEnd','status'],...state.days.map(d=>[d.day,d.start||'',d.originalEnd||'',d.end||'',d.kind])]),'text/csv;charset=utf-8');return;}
  if(action==='save-draft'){if(!allowRole('hr'))return;const d=draftData();if(!d?.title){formError('กรอกหัวข้อก่อนบันทึกร่าง (ช่องว่างอย่างเดียวไม่นับ)');return;}const existing=state.drafts.find(x=>x.id===loadedDraft);if(existing)Object.assign(existing,d);else state.drafts.push({...d,id:'d'+(++draftSeq)});loadedDraft='';dirty=false;render();toast(existing?'อัปเดตร่างเดิมในตัวอย่างแล้ว':'บันทึกร่างในตัวอย่างแล้ว');return;}
  if(action==='load-draft'){if(!allowRole('hr')||!allowDiscard())return;const d=state.drafts.find(x=>x.id===id);if(!d)return;loadedDraft=d.id;render();const form=$('#publish-form');for(const key of ['title','body','date'])form.elements[key].value=d[key];form.elements.pinned.checked=d.pinned;dirty=false;form.elements.title.focus();return;}
  if(action==='import-template'){download('DEMO-payslip-import.csv',importSample,'text/csv;charset=utf-8');return;}
  if(action==='load-import'){if(!allowRole('hr'))return;importToken++;Object.assign(state,{importRows:validateImport(importSample),importFor:importPeriod,importReading:false,importDone:null,importError:'',importSource:'ข้อมูลตัวอย่าง DEMO-payslip-import.csv'});render();return;}
  if(action==='publish-import'){if(!allowRole('hr'))return;const selected=state.importRows.filter(r=>r.selected);if(state.importReading||state.importFor!==importPeriod||!selected.length||selected.some(r=>r.errors.length)||!/^202[67]-(0[1-9]|1[0-2])$/.test(importPeriod))return;const month=Number(importPeriod.slice(5)),yr=Number(importPeriod.slice(0,4));if(state.payslips.some(p=>p.month===month&&p.year===yr))return;const lastDay=new Date(Date.UTC(yr,month,0)).getUTCDate();selected.forEach(r=>state.payslips.unshift({id:'p-'+importPeriod,month,year:yr,version:1,base:sumBaht(r.base),ot:sumBaht(r.ot),other:sumBaht(r.other),deduction:sumBaht(r.deduction),payDate:importPeriod+'-'+lastDay}));state.importDone={period:importPeriod,count:selected.length};addNotification('สลิปเงินเดือนงวดใหม่เผยแพร่แล้ว',monthLabel(yr,month)+' · เวอร์ชัน 1','payslip/p-'+importPeriod);render();toast('เผยแพร่ '+selected.length+' แถว งวด '+monthLabel(yr,month)+' ในตัวอย่างแล้ว');return;}
}
document.addEventListener('click',event=>{const dialog=$('#dialog');if(event.target===dialog){/* Click on the native dialog backdrop closes it. */const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom){closeDialog();return;}}const a=event.target.closest('a[href^="#"]');if(a){if(!allowDiscard()){event.preventDefault();return;}if(a.dataset.dismissDialog!==undefined)closeDialog();if(routeInfo().page==='customize'&&a.hash!=='#customize')prefDraft=null;if(a.closest('#sidebar')&&menuOpen()&&a.hash===(location.hash||'#home')){/* Same-route link: close the drawer and move focus to the content. */setMenu(false,{restore:false});$('#main')?.focus();}}const el=event.target.closest('[data-action]');if(el&&!el.disabled)doAction(el);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menuOpen()&&!$('#dialog').open){e.preventDefault();setMenu(false);}});
$('#dialog').addEventListener('close',restoreDialogFocus);
matchMedia('(min-width: 901px)').addEventListener('change',e=>{if(e.matches&&menuOpen())setMenu(false,{restore:false});});
document.addEventListener('input',event=>{if(event.target.closest('#leave-form')){dirty=true;updateCharge();}else if(event.target.closest('#correction-form,#publish-form,#policy-form'))dirty=true;if(event.target.id==='request-search'){const pos=event.target.selectionStart;query=event.target.value;render();const input=$('#request-search');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('change',async event=>{const el=event.target;
  if(el.id==='role'){if(!allowDiscard()){el.value=role;return;}role=el.value;prefDraft=null;loadedDraft='';clearVerification();closeDialog();if(role!=='hr'&&state.importReading){importToken++;state.importReading=false;state.importSource='';}render();$('#role')?.focus();}
  if(el.id==='response'){if(!allowDiscard()){el.value=responseState;return;}responseState=el.value;render();}
  if(el.id==='request-filter'){filter=el.value;render();}
  if(el.id==='attendance-kind'){attendanceKind=el.value;render();}
  if(el.id==='holiday-year'){holidayYear=el.value;render();$('#holiday-year')?.focus();}
  if(el.id==='payslip-year'){payslipYear=el.value;render();$('#payslip-year')?.focus();}
  if(el.dataset.shortcut&&prefDraft){const p=prefDraft.find(p=>p.id===el.dataset.shortcut);if(!p)return;p.visible=el.checked;dirty=prefsChanged();render();$(`[data-shortcut="${p.id}"]`)?.focus();}
  if(el.dataset.importRow!==undefined){const row=state.importRows[Number(el.dataset.importRow)];if(!row||!allowRole('hr'))return;row.selected=el.checked;render();$(`[data-import-row="${el.dataset.importRow}"]`)?.focus();}
  if(el.id==='import-period'){/* Rows are checked for one period; a new period needs a new read. */importPeriod=el.value;importToken++;Object.assign(state,{importRows:[],importFor:'',importReading:false,importDone:null,importError:'',importSource:''});render();$('#import-period')?.focus();}
  if(el.id==='import-file'){const file=el.files[0];if(!file||!allowRole('hr'))return;/* Invalidate prior staging before the async read so a failed replacement can never leave old rows publishable. */const token=++importToken,snapshot=state,period=importPeriod;Object.assign(state,{importRows:[],importFor:'',importReading:true,importDone:null,importError:'',importSource:file.name});render();let rows=null,error='';try{if(file.size>100000)throw new Error('ไฟล์ต้องมีขนาดไม่เกิน 100 KB');rows=validateImport(await file.text());}catch(e){error=e.message||'อ่านไฟล์ไม่สำเร็จ';}if(token!==importToken||snapshot!==state)return;if(role!=='hr'||routeInfo().page!=='import'||period!==importPeriod){Object.assign(state,{importReading:false,importSource:''});return;}Object.assign(state,{importReading:false,importRows:error?[]:rows,importFor:error?'':period,importError:error});render();$(error?'#import-file':'[data-import-row="0"]')?.focus();}
});
document.addEventListener('submit',event=>{const form=event.target;event.preventDefault();const data=Object.fromEntries(new FormData(form));
  if(form.id==='leave-form'){if(!allowRole('employee'))return;if(!validIso(data.from)||!validIso(data.to)){formError('เลือกวันที่เริ่มและสิ้นสุดที่มีอยู่จริง');return;}if(data.from>data.to){formError('วันที่สิ้นสุดต้องไม่ก่อนวันที่เริ่ม');return;}if(!types[data.type]){formError('เลือกประเภทการลา');return;}const days=chargedDays(data.from,data.to,data.unit);const units=days?.reduce((n,d)=>n+d.units,0);if(!data.reason.trim()){formError('ระบุเหตุผลก่อนส่งคำขอ');return;}if(!days||!units){formError('เลือกช่วงวันทำงานที่ถูกต้อง ไม่เกิน 31 วัน');return;}if(data.from<'2026-01-01'||data.to>'2026-12-31'){formError('ตัวอย่างรองรับวันที่ในปีสิทธิ์ 2569 เท่านั้น');return;}const b=balance(data.type);if(units>b.available){formError('ยอดพร้อมใช้ไม่เพียงพอ เลือกวันใหม่หรือติดต่อ HR');return;}const existing=state.requests.find(r=>r.id===form.dataset.request);if(existing&&existing.status!=='RETURNED'){formError('สถานะคำขอเปลี่ยนแล้ว กรุณาเปิดรายการอีกครั้ง');return;}if(state.requests.some(r=>r.type!=='correction'&&r.status!=='RETURNED'&&r.id!==existing?.id&&r.from<=data.to&&r.to>=data.from)){formError('ช่วงวันที่ทับซ้อนกับคำขอที่รอพิจารณาหรือรับรองแล้ว');return;}const details={type:data.type,title:types[data.type].label,from:data.from,to:data.to,reason:data.reason.trim(),units,status:'PENDING',returnReason:''};const history=['ส่งคำขอ'+(existing?'ใหม่':''),'12 ต.ค. 2569 · ตัวอย่าง','มินตรา · สำรองสิทธิ์ '+units+' วัน'];if(existing){Object.assign(existing,details);existing.history.push(history);}else{state.requests.unshift({id:'r'+Date.now(),...details,history:[history]});}dirty=false;location.hash='request/'+(existing?.id||state.requests[0].id);toast('ส่งคำขอและสำรองสิทธิ์ในตัวอย่างแล้ว');}
  if(form.id==='correction-form'){if(!allowRole('employee'))return;const d=state.days.find(d=>d.day===form.dataset.day);if(!data.reason.trim()){formError('ระบุเหตุผลก่อนส่งคำขอ');return;}if(!d||!d.start||['NONWORKING','LEAVE','ONGOING'].includes(d.kind)){formError('วันนี้ไม่มีเวลาเข้างานที่ขอแก้ไขได้ในตัวอย่าง');return;}if(!/^\d{2}:\d{2}$/.test(data.end||'')||data.end<=d.start){formError('เวลาออกต้องหลังเวลาเข้าในตัวอย่างกะวันเดียวนี้');return;}if(data.end===d.end){formError('เวลาที่เสนอตรงกับเวลาออกที่มีผลอยู่แล้ว');return;}const existing=state.requests.find(r=>r.id===form.dataset.request);if(existing&&existing.status!=='RETURNED'){formError('สถานะคำขอเปลี่ยนแล้ว กรุณาเปิดรายการอีกครั้ง');return;}if(state.requests.some(r=>r.type==='correction'&&r.from===d.day&&r.status!=='RETURNED')){formError('วันนี้มีคำขอแก้ไขที่รอพิจารณาหรือรับรองแล้ว');return;}const history=['ส่งคำขอ'+(existing?'ใหม่':''),'12 ต.ค. 2569 · ตัวอย่าง','มินตรา'];if(existing){existing.reason=data.reason.trim();existing.proposed=data.end;existing.status='PENDING';existing.returnReason='';existing.history.push(history);}else state.requests.unshift({id:nextId('r'),type:'correction',title:'แก้ไขเวลาออกงาน',from:d.day,to:d.day,status:'PENDING',reason:data.reason.trim(),proposed:data.end,units:0,history:[history]});dirty=false;location.hash='request/'+(existing?.id||state.requests[0].id);toast('ส่งคำขอแก้ไขในตัวอย่างแล้ว');}
  if(form.id==='return-form'){if(!data.reason.trim()){formError('ต้องระบุเหตุผลที่ส่งกลับ');return;}closeDialog();reviewDecision(form.dataset.request,'RETURNED',data.reason.trim());}
  if(form.id==='policy-form'){if(!allowRole('hr'))return;const name=(data.name||'').trim(),annual=policyNumber(data.annual),carry=policyNumber(data.carry),half=data.half==='on';const problem=!name?'ระบุชื่อนโยบาย (ช่องว่างอย่างเดียวไม่นับ)':!validIso(data.effective)||data.effective<'2027-01-01'||data.effective>'2027-12-31'?'วันที่มีผลต้องเป็นวันที่จริงในปี 2570':!Number.isFinite(annual)||annual>365?'สิทธิ์ลาพักร้อนต้องเป็น 0–365 วัน ทีละ 0.5 วัน':!Number.isFinite(carry)||carry>annual?'ยอดยกมาต้องไม่ติดลบและไม่เกินสิทธิ์ลาพักร้อน':!half&&(!Number.isInteger(annual)||!Number.isInteger(carry))?'เมื่อไม่รองรับครึ่งวัน สิทธิ์และยอดยกมาต้องเป็นจำนวนวันเต็ม':'';if(problem){formError(problem);return;}const prev=state.policyVersions[1];const next={version:2,name,effective:data.effective,annual:String(annual),carry:String(carry),half,revision:(prev?.revision||0)+1};if(prev&&['name','effective','annual','carry','half'].every(k=>prev[k]===next[k])){formError('ค่าตรงกับ v2 ที่บันทึกไว้แล้ว ไม่มีการเปลี่ยนแปลง');return;}state.policyVersions[1]=next;dirty=false;render();toast('บันทึกนโยบาย v2 ในตัวอย่างแล้ว');}
  if(form.id==='publish-form'){if(!allowRole('hr'))return;const d=draftData();if(!d.title||!d.body||!validIso(d.date)||d.date>'2026-10-12'){formError('กรอกหัวข้อ เนื้อหา และวันเผยแพร่ที่มีจริงไม่เกินวันตัวอย่าง');return;}const id=nextId('a');state.announcements.unshift({...d,id,read:false,author:'ฝ่ายทรัพยากรบุคคล'});/* Publishing a loaded draft consumes it. */if(loadedDraft)state.drafts=state.drafts.filter(x=>x.id!==loadedDraft);loadedDraft='';addNotification('ประกาศใหม่จากฝ่าย HR',d.title,'announcement/'+id);dirty=false;render();toast('เผยแพร่ในตัวอย่างแล้ว');}
});
let previousHash=location.hash||'#home',ignoreHash=false;
window.addEventListener('hashchange',()=>{if(ignoreHash){ignoreHash=false;return;}if(!allowDiscard()){ignoreHash=true;location.hash=previousHash;return;}previousHash=location.hash;responseState='normal';closeDialog();if(routeInfo().page!=='customize')prefDraft=null;if(routeInfo().page!=='publish')loadedDraft='';if(state.importReading&&routeInfo().page!=='import'){importToken++;state.importReading=false;state.importSource='';}render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
render();
